package com.alsafa.native4;
import android.app.Activity;import android.os.Bundle;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.TextView;import com.alsafa.native4.core.*;import java.text.SimpleDateFormat;import java.util.Date;import java.util.Locale;
public final class ClosingActivity extends Activity{
 private CoreDb coreDb;private Native4Services services;private DailyClosingStore closingStore;private NextDayOpeningStore nextDayStore;private WorkDayFxPanelBinder fxPanel;private TextView status,expectedClosing,drawerOut,latestCarryPreview;private EditText closingDay,openingUsd,openingTry,openingSyp,countedUsd,countedTry,countedSyp,carryUsd,carryTry,carrySyp,closingNotes;
 @Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_closing);coreDb=new CoreDb(this);services=new Native4Services(coreDb,"native4-android-alpha");closingStore=services.closing;nextDayStore=services.nextDayOpening;status=findViewById(R.id.status);expectedClosing=findViewById(R.id.expectedClosing);drawerOut=findViewById(R.id.drawerOut);latestCarryPreview=findViewById(R.id.latestCarryPreview);closingDay=findViewById(R.id.closingDay);openingUsd=findViewById(R.id.openingUsd);openingTry=findViewById(R.id.openingTry);openingSyp=findViewById(R.id.openingSyp);countedUsd=findViewById(R.id.countedUsd);countedTry=findViewById(R.id.countedTry);countedSyp=findViewById(R.id.countedSyp);carryUsd=findViewById(R.id.carryUsd);carryTry=findViewById(R.id.carryTry);carrySyp=findViewById(R.id.carrySyp);closingNotes=findViewById(R.id.closingNotes);closingDay.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));fxPanel=new WorkDayFxPanelBinder(this,services,(LinearLayout)findViewById(R.id.closingPanel));fxPanel.load(day());findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.openWorkDay).setOnClickListener(v->openWorkDay());findViewById(R.id.useLatestCarry).setOnClickListener(v->openFromLatestCarry());findViewById(R.id.refreshExpected).setOnClickListener(v->refreshExpected());findViewById(R.id.calcDrawerOut).setOnClickListener(v->calculateDrawerOut());findViewById(R.id.closeWorkDay).setOnClickListener(v->closeWorkDay());refreshCarryPreview();refreshExpectedQuietly();}
 private void openWorkDay(){try{fxPanel.requireValues();fxPanel.save(day());closingStore.open(day(),money(openingUsd),money(openingTry),money(openingSyp),"");Native4BackgroundSync.request(this);status.setText("✓ تم اعتماد أسعار الصرف وفتح يوم العمل محلياً + Outbox");refreshExpected();}catch(Exception e){status.setText("لم يُفتح يوم العمل: "+msg(e));}}
 private void openFromLatestCarry(){try{fxPanel.requireValues();fxPanel.save(day());ClosingCarryStore.Carry c=nextDayStore.open(day());Native4BackgroundSync.request(this);openingUsd.setText(fmt(c.usd));openingTry.setText(fmt(c.tryAmount));openingSyp.setText(fmt(c.syp));status.setText("✓ تم فتح اليوم من مدوّر إقفال "+c.businessDay);refreshCarryPreview();refreshExpected();}catch(Exception e){status.setText("لم يُفتح اليوم من المدوّر: "+msg(e));}}
 private void refreshCarryPreview(){ClosingCarryStore.Carry c=nextDayStore.preview();latestCarryPreview.setText(c==null?"آخر مدوّر محفوظ: لا يوجد إقفال سابق":"آخر مدوّر محفوظ من "+c.businessDay+" — USD: "+fmt(c.usd)+" | TRY: "+fmt(c.tryAmount)+" | SYP: "+fmt(c.syp));}
 private void refreshExpected(){try{DailyClosingStore.Expected e=closingStore.expected(day());expectedClosing.setText("المتوقع — USD: "+fmt(e.usd)+" | TRY: "+fmt(e.tryAmount)+" | SYP: "+fmt(e.syp));status.setText("✓ تم تحديث المتوقع من مدوّر البداية وحركات هذا اليوم فقط");}catch(Exception e){expectedClosing.setText("المتوقع: —");status.setText("تعذر حساب المتوقع: "+msg(e));}}
 private void refreshExpectedQuietly(){try{DailyClosingStore.Expected e=closingStore.expected(day());expectedClosing.setText("المتوقع — USD: "+fmt(e.usd)+" | TRY: "+fmt(e.tryAmount)+" | SYP: "+fmt(e.syp));}catch(Exception ignored){expectedClosing.setText("المتوقع: افتح يوم العمل أولاً");}}
 private void calculateDrawerOut(){try{double u=drawer(money(countedUsd),money(carryUsd)),t=drawer(money(countedTry),money(carryTry)),s=drawer(money(countedSyp),money(carrySyp));drawerOut.setText("الخارج من الدرج — USD: "+fmt(u)+" | TRY: "+fmt(t)+" | SYP: "+fmt(s));status.setText("✓ تم الحساب دون تحويل بين العملات");}catch(Exception e){status.setText("تعذر الحساب: "+msg(e));}}
 private void closeWorkDay(){try{double cu=money(countedUsd),ct=money(countedTry),cs=money(countedSyp),ku=money(carryUsd),kt=money(carryTry),ks=money(carrySyp);String id=closingStore.close(day(),cu,ct,cs,ku,kt,ks,closingNotes.getText().toString());Native4BackgroundSync.request(this);drawerOut.setText("الخارج من الدرج — USD: "+fmt(drawer(cu,ku))+" | TRY: "+fmt(drawer(ct,kt))+" | SYP: "+fmt(drawer(cs,ks)));status.setText("✓ تم إقفال اليوم محلياً وتثبيت المدوّر. المرجع: "+id);expectedClosing.setText("اليوم مقفل — المدوّر المحفوظ هو فقط ما سيبدأ به اليوم التالي");refreshCarryPreview();Native4AutoSync.request(this,coreDb,null);}catch(Exception e){status.setText("لم يتم الإقفال: "+msg(e));}}
 private String day(){return closingDay.getText().toString().trim();}private static double money(EditText e){String v=e.getText().toString().trim();return v.isEmpty()?0:Double.parseDouble(v);}private static double drawer(double counted,double carry){if(!Double.isFinite(counted)||!Double.isFinite(carry)||counted<0||carry<0||carry>counted)throw new IllegalArgumentException("المدوّر يجب أن يكون بين صفر والمبلغ المعدود");return counted-carry;}private static String fmt(double v){return String.format(Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}